1	package nexusbench
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"slices"
8		"strings"
9	)
10	
11	// Op is what a run of the bench is about to do; it decides which checks the
12	// preflight makes.
13	type Op int
14	
15	const (
16		OpUp Op = iota
17		OpProvision
18		OpDown
19		OpStatus
20	)
21	
22	// PreflightResult is what a successful preflight learned about the cluster.
23	type PreflightResult struct {
24		// NamespaceExists is true when the bench namespace is there.
25		NamespaceExists bool
26		// NamespaceOurs is true when it carries our managed-by label.
27		NamespaceOurs bool
28		// NodeIP is the InternalIP of the first node that reports one; empty when
29		// none does, which is not an error (the other hosts still work). It is not
30		// read for OpDown.
31		NodeIP string
32	}
33	
34	const (
35		// managedByLabel and managedByValue are the label 00-namespace.yaml.tmpl
36		// puts on the namespace; down deletes a namespace only when it carries it.
37		managedByLabel = "app.kubernetes.io/managed-by"
38		managedByValue = "devdesk-nexus-bench"
39	
40		// nexusServiceName is the Service 30-service.yaml.tmpl creates.
41		nexusServiceName = "nexus"
42	
43		// requestTimeout bounds every call that reaches the API server.
44		requestTimeout = "--request-timeout=10s"
45	)
46	
47	// permissionScope says where a can-i question applies.
48	type permissionScope int
49	
50	const (
51		scopeCluster   permissionScope = iota // no flag: cluster-scoped resources
52		scopeNamespace                        // -n <namespace>
53		scopeAll                              // -A
54	)
55	
56	// permission is one "kubectl auth can-i" question the preflight asks.
57	type permission struct {
58		verb, resource string
59		scope          permissionScope
60	}
61	
62	// permissionsByOp is the list F2 of the plan: what each operation needs. An
63	// operation absent from the map (status) writes nothing and asks nothing.
64	var permissionsByOp = map[Op][]permission{
65		OpUp: {
66			{"create", "namespaces", scopeCluster},
67			{"create", "persistentvolumeclaims", scopeNamespace},
68			{"create", "services", scopeNamespace},
69			{"create", "deployments", scopeNamespace},
70			{"create", "secrets", scopeNamespace},
71			{"create", "pods/exec", scopeNamespace},
72			{"list", "services", scopeAll},
73		},
74		OpProvision: {{"create", "pods/exec", scopeNamespace}},
75		OpDown:      {{"delete", "namespaces", scopeCluster}},
76	}
77	
78	// RunPreflight checks, with read-only kubectl calls, that op can go ahead, and
79	// returns what it learned. Nothing is written to the cluster, whatever the
80	// outcome: a failure here means no write was ever issued. The checks run in a
81	// fixed order and stop at the first failure, so nothing is asked of a cluster
82	// the context does not reach:
83	//
84	//  1. the parameters (no call at all)
85	//  2. the context is in the kubeconfig
86	//  3. the API server answers /readyz
87	//  4. the can-i questions of the operation
88	//  5. the namespace: absent, ours, or foreign
89	//  6. up only: no other Service holds one of our NodePorts
90	//  7. all but down: the InternalIP of the node
91	//
92	// Every failure is a *BenchError.
93	func RunPreflight(ctx context.Context, r Runner, p Params, op Op) (PreflightResult, error) {
94		var res PreflightResult
95		if err := p.Validate(); err != nil {
96			return res, err
97		}
98		pf := preflight{r: r, p: p}
99		if err := pf.checkContext(ctx); err != nil {
100			return res, err
101		}
102		if err := pf.checkReachable(ctx); err != nil {
103			return res, err
104		}
105		for _, perm := range permissionsByOp[op] {
106			if err := pf.checkPermission(ctx, perm); err != nil {
107				return res, err
108			}
109		}
110		res, err := pf.checkNamespace(ctx, op)
111		if err != nil {
112			return res, err
113		}
114		if op == OpUp {
115			if err := pf.checkNodePorts(ctx); err != nil {
116				return res, err
117			}
118		}
119		if op != OpDown {
120			if res.NodeIP, err = pf.nodeIP(ctx); err != nil {
121				return res, err
122			}
123		}
124		return res, nil
125	}
126	
127	type preflight struct {
128		r Runner
129		p Params
130	}
131	
132	// local runs a call that does not reach the API server.
133	func (pf preflight) local(ctx context.Context, args ...string) (stdout, stderr string, err error) {
134		out, errOut, err := pf.r.Run(ctx, nil, args...)
135		return string(out), string(errOut), err
136	}
137	
138	// remote runs a call that reaches the API server, under a request timeout.
139	func (pf preflight) remote(ctx context.Context, args ...string) (stdout, stderr string, err error) {
140		return pf.local(ctx, slices.Concat(args, []string{requestTimeout})...)
141	}
142	
143	// command is the kubectl command line a user can run to repeat a call.
144	func (pf preflight) command(args ...string) string {
145		return "kubectl --context " + pf.p.Context + " " + strings.Join(args, " ")
146	}
147	
148	// failure turns a failed kubectl call into a BenchError whose kind comes from
149	// the stderr. Neither the stderr nor the sub-process error reaches the message.
150	func (pf preflight) failure(what string, args []string, stderr string, err error) *BenchError {
151		kind := classifyKubectl(stderr)
152		reason := "kubectl failed"
153		switch kind {
154		case Forbidden:
155			reason = "the API server refused the request (forbidden)"
156		case ClusterUnreachable:
157			reason = "the cluster did not answer"
158		}
159		return &BenchError{
160			Kind:  kind,
161			Cause: "could not " + what + ": " + reason,
162			Check: pf.command(args...),
163			Err:   err,
164		}
165	}
166	
167	func (pf preflight) checkContext(ctx context.Context) error {
168		args := []string{"config", "get-contexts", "-o", "name"}
169		out, errOut, err := pf.local(ctx, args...)
170		if err != nil {
171			return pf.failure("list the kubeconfig contexts", args, errOut, err)
172		}
173		for _, line := range strings.Split(out, "\n") {
174			if strings.TrimSpace(line) == pf.p.Context {
175				return nil
176			}
177		}
178		return &BenchError{
179			Kind:  ContextNotFound,
180			Cause: fmt.Sprintf("no kubeconfig context is named %q", pf.p.Context),
181			Check: "kubectl config get-contexts -o name, then set NEXUS_BENCH_CONTEXT to one of them",
182		}
183	}
184	
185	func (pf preflight) checkReachable(ctx context.Context) error {
186		args := []string{"get", "--raw", "/readyz"}
187		_, errOut, err := pf.remote(ctx, args...)
188		if err == nil {
189			return nil
190		}
191		// A refusal (an expired token, a 403) is not an absent cluster: say so.
192		// Anything else, classified or not, means the server did not answer.
193		if classifyKubectl(errOut) == Forbidden {
194			return pf.failure("reach the API server", args, errOut, err)
195		}
196		return &BenchError{
197			Kind:  ClusterUnreachable,
198			Cause: fmt.Sprintf("the API server of context %q does not answer /readyz", pf.p.Context),
199			Check: pf.command(args...),
200			Err:   err,
201		}
202	}
203	
204	// checkPermission asks "kubectl auth can-i". A "no" arrives on stdout with a
205	// non-zero exit, so the answer is read before the error.
206	func (pf preflight) checkPermission(ctx context.Context, perm permission) error {
207		args := []string{"auth", "can-i", perm.verb, perm.resource}
208		where := "cluster-wide"
209		switch perm.scope {
210		case scopeNamespace:
211			args = append(args, "-n", pf.p.Namespace)
212			where = fmt.Sprintf("in namespace %q", pf.p.Namespace)
213		case scopeAll:
214			args = append(args, "-A")
215			where = "in all namespaces"
216		}
217		out, errOut, err := pf.remote(ctx, args...)
218		answer := strings.TrimSpace(out)
219		switch {
220		case strings.HasPrefix(answer, "no"):
221			return &BenchError{
222				Kind:  Forbidden,
223				Cause: fmt.Sprintf("the current user is not allowed to %s %s %s", perm.verb, perm.resource, where),
224				Check: pf.command(args...),
225				Err:   err,
226			}
227		case err == nil && strings.HasPrefix(answer, "yes"):
228			return nil
229		}
230		return pf.failure(fmt.Sprintf("check the permission to %s %s", perm.verb, perm.resource), args, errOut, err)
231	}
232	
233	// namespaceObject is the part of a Namespace the preflight reads.
234	type namespaceObject struct {
235		Metadata struct {
236			Labels map[string]string `json:"labels"`
237		} `json:"metadata"`
238	}
239	
240	func (pf preflight) checkNamespace(ctx context.Context, op Op) (PreflightResult, error) {
241		var res PreflightResult
242		ns := pf.p.Namespace
243		args := []string{"get", "namespace", ns, "-o", "json"}
244		out, errOut, err := pf.remote(ctx, args...)
245		switch {
246		case err != nil && isNotFound(errOut):
247			// Absent: only provision and status need it.
248			if op == OpProvision || op == OpStatus {
249				return res, &BenchError{
250					Kind:  NamespaceMissing,
251					Cause: fmt.Sprintf("namespace %q does not exist", ns),
252					Check: pf.command(args[:3]...) + ", then run `mise run nexus-bench:up`",
253					Err:   err,
254				}
255			}
256			return res, nil
257		case err != nil:
258			return res, pf.failure(fmt.Sprintf("read the namespace %q", ns), args, errOut, err)
259		}
260	
261		var obj namespaceObject
262		if err := json.Unmarshal([]byte(out), &obj); err != nil {
263			return res, &BenchError{
264				Kind:  Unclassified,
265				Cause: fmt.Sprintf("kubectl answered with something that is not a Namespace for %q", ns),
266				Check: pf.command(args...),
267				Err:   err,
268			}
269		}
270		res.NamespaceExists = true
271		res.NamespaceOurs = obj.Metadata.Labels[managedByLabel] == managedByValue
272		if !res.NamespaceOurs {
273			return res, &BenchError{
274				Kind:  NamespaceForeign,
275				Cause: fmt.Sprintf("namespace %q exists but does not carry the label %s=%s, so the bench did not create it", ns, managedByLabel, managedByValue),
276				Check: pf.command("get", "namespace", ns, "--show-labels") + ", or choose another NEXUS_BENCH_NAMESPACE",
277			}
278		}
279		return res, nil
280	}
281	
282	// serviceList is the part of a Service list the preflight reads.
283	type serviceList struct {
284		Items []struct {
285			Metadata struct {
286				Name      string `json:"name"`
287				Namespace string `json:"namespace"`
288			} `json:"metadata"`
289			Spec struct {
290				Ports []struct {
291					NodePort int `json:"nodePort"`
292				} `json:"ports"`
293			} `json:"spec"`
294		} `json:"items"`
295	}
296	
297	// checkNodePorts reads every Service of the cluster: the list of taken
298	// NodePorts is not a constant (F1). Our own Service, in our namespace, may hold
299	// them: that is a second up.
300	func (pf preflight) checkNodePorts(ctx context.Context) error {
301		args := []string{"get", "services", "-A", "-o", "json"}
302		out, errOut, err := pf.remote(ctx, args...)
303		if err != nil {
304			return pf.failure("list the Services of the cluster", args, errOut, err)
305		}
306		var list serviceList
307		if err := json.Unmarshal([]byte(out), &list); err != nil {
308			return &BenchError{
309				Kind:  Unclassified,
310				Cause: "kubectl answered with something that is not a Service list",
311				Check: pf.command(args...),
312				Err:   err,
313			}
314		}
315		var taken []string
316		for _, svc := range list.Items {
317			if svc.Metadata.Namespace == pf.p.Namespace && svc.Metadata.Name == nexusServiceName {
318				continue
319			}
320			for _, port := range svc.Spec.Ports {
321				if port.NodePort == pf.p.HTTPNodePort || port.NodePort == pf.p.DockerNodePort {
322					taken = append(taken, fmt.Sprintf("%d is held by Service %s/%s", port.NodePort, svc.Metadata.Namespace, svc.Metadata.Name))
323				}
324			}
325		}
326		if len(taken) > 0 {
327			return &BenchError{
328				Kind:  NodePortTaken,
329				Cause: "NodePort " + strings.Join(taken, ", "),
330				Check: pf.command(args...) + ", then set NEXUS_BENCH_HTTP_NODEPORT and NEXUS_BENCH_DOCKER_NODEPORT to free ports",
331			}
332		}
333		return nil
334	}
335	
336	// nodeList is the part of a Node list the preflight reads.
337	type nodeList struct {
338		Items []struct {
339			Status struct {
340				Addresses []struct {
341					Type    string `json:"type"`
342					Address string `json:"address"`
343				} `json:"addresses"`
344			} `json:"status"`
345		} `json:"items"`
346	}
347	
348	// nodeIP returns the first InternalIP any node reports, or "" when none does.
349	func (pf preflight) nodeIP(ctx context.Context) (string, error) {
350		args := []string{"get", "nodes", "-o", "json"}
351		out, errOut, err := pf.remote(ctx, args...)
352		if err != nil {
353			return "", pf.failure("read the nodes", args, errOut, err)
354		}
355		var nodes nodeList
356		if err := json.Unmarshal([]byte(out), &nodes); err != nil {
357			return "", &BenchError{
358				Kind:  Unclassified,
359				Cause: "kubectl answered with something that is not a Node list",
360				Check: pf.command(args...),
361				Err:   err,
362			}
363		}
364		for _, node := range nodes.Items {
365			for _, addr := range node.Status.Addresses {
366				if addr.Type == "InternalIP" {
367					return addr.Address, nil
368				}
369			}
370		}
371		return "", nil
372	}
