package nexusbench

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"strings"
	"time"
)

type Clock interface {
	Now() time.Time
	Sleep(ctx context.Context, d time.Duration) error
}

func Destroy(ctx context.Context, r Runner, clk Clock, store SecretStore, p Params, out io.Writer) error {
	res, err := RunPreflight(ctx, r, p, OpDown)
	if err != nil {
		return err
	}
	if !res.NamespaceExists {
		fmt.Fprintln(out, "nothing to delete")
		return nil
	}
	ns := p.Namespace
	_, se, err := r.Run(ctx, nil, "delete", "namespace", ns, "--wait=false")
	if err != nil {
		return &BenchError{Kind: classifyKubectl(string(se)), Cause: "could not delete", Check: "kubectl get namespace " + ns, Err: err}
	}
	start := clk.Now()
	for {
		o, se, err := r.Run(ctx, nil, "get", "namespace", ns, "-o", "json")
		if err != nil {
			if isNotFound(string(se)) {
				break
			}
			return err
		}
		if clk.Now().Sub(start) >= p.DeleteTimeout {
			var obj struct {
				Spec   struct{ Finalizers []string }
				Status struct{ Conditions []struct{ Type, Message string } }
			}
			_ = json.Unmarshal(o, &obj)
			return &BenchError{Kind: Deadline, Cause: fmt.Sprintf("namespace %s still terminating: finalizers %v conditions %+v", ns, obj.Spec.Finalizers, obj.Status.Conditions), Check: "kubectl get namespace " + ns + " -o json"}
		}
		if err := clk.Sleep(ctx, 5*time.Second); err != nil {
			return err
		}
	}
	o, _, err := r.Run(ctx, nil, "get", "pv", "-o", "json")
	if err == nil {
		var l struct{ Items []struct {
			Metadata struct{ Name string }
			Spec struct{ ClaimRef *struct{ Namespace string } }
		} }
		_ = json.Unmarshal(o, &l)
		var names []string
		for _, i := range l.Items {
			if i.Spec.ClaimRef != nil && i.Spec.ClaimRef.Namespace == ns {
				names = append(names, i.Metadata.Name)
			}
		}
		if len(names) > 0 {
			fmt.Fprintf(out, "warning: volumes left: %s\n", strings.Join(names, ", "))
		}
	}
	return store.Remove()
}
EOF
